 [('Je peux reformuler','Je peux exprimer le même sens autrement.','Si le mot est nouveau, je peux reformuler.'),('Sans perdre le sens','En conservant l’idée importante.','Je raccourcis la phrase sans perdre le sens.'),('C’est plus parlant','Cela rend l’idée plus facile à comprendre.','Avec cet exemple, c’est plus parlant.')],
 [('Je prends du recul','Je regarde la situation avec un peu de distance.','Avant de tout changer, je prends du recul.'),('À y regarder de près','Après une observation attentive.','À y regarder de près, les deux problèmes sont différents.'),('Il y a une nuance','Une petite différence de sens mérite attention.','Ces mots sont proches, mais il y a une nuance.')],
 [('Je garde cette idée','Je souhaite retenir cette proposition.','Je garde cette idée pour mon prochain cours.'),('Ça peut servir','Cela peut être utile dans une autre situation.','Je note cet exemple, ça peut servir.'),('À reprendre plus tard','Un point peut attendre une autre occasion.','C’est une question intéressante, à reprendre plus tard.')],
 [('Je tiens à comprendre','Comprendre ce point est important pour moi.','Je tiens à comprendre pourquoi l’ordre change le résultat.'),('C’est une piste','C’est une possibilité à examiner.','Cet exemple ne donne pas toute la réponse, mais c’est une piste.'),('À vérifier','Cela demande une confirmation.','Le nom du lieu est à vérifier avant la publication.')],
 [('Je fais le lien','Je comprends une relation entre plusieurs éléments.','Je fais le lien entre cette règle et mon propre exemple.'),('Je retiens surtout','Je choisis le point principal à garder en mémoire.','Je retiens surtout l’importance de préciser le contexte.'),('La suite se prépare','La prochaine étape peut être organisée à partir de ce qui existe.','Avec ces notes, la suite se prépare plus facilement.')]
