CATEGORY_REFLECTIONS={
 'La vie quotidienne':'Dans une situation ordinaire, la compétence se reconnaît souvent à la justesse d’un ajustement plutôt qu’à la complexité de l’action. Une demande claire, un repère écrit ou un essai limité peut suffire à réduire une difficulté réelle. L’autonomie n’exclut pas l’aide : elle comprend aussi la capacité à savoir quelle aide demander et comment l’utiliser ensuite.',
 'Histoires originales':'Le récit donne accès à certains gestes et à quelques décisions, mais il ne dévoile pas toute la pensée des personnages. Une interprétation peut donc s’appuyer sur les indices du texte tout en restant ouverte. Distinguer ce qui est raconté de ce que l’on imagine permet de développer une lecture personnelle sans la présenter comme l’unique sens possible.',
 'Histoires, arts et découvertes':'Découvrir un objet, un lieu ou une pratique demande d’articuler curiosité et attention au contexte. Une représentation peut guider le regard tout en simplifiant ce qu’elle montre. Le lecteur peut ainsi s’intéresser à ce qui devient visible, mais également aux informations absentes et aux autres points de vue qui pourraient compléter sa compréhension.'
}

def de_action(action):
 return ('d’' if action[0].lower() in 'aeiouyàâéèêëîïôùûühœ' else 'de ')+action

def contextual_grammar(action,index,visit):
 d=de_action(action)
 foundation=[
  ('Vouloir + infinitif',f'Je voudrais de {action}.',f'Je voudrais {action}.','Après voudrais, l’infinitif vient directement.'),
  ('Pouvoir + infinitif',f'Nous pouvons à {action}.',f'Nous pouvons {action}.','Après pouvoir, on n’ajoute pas de préposition devant l’infinitif.'),
  ('Le futur proche',f'Elle va de {action}.',f'Elle va {action}.','Pour ce futur proche, aller est suivi directement de l’infinitif.'),
  ('Il faut + infinitif',f'Il faut de {action}.',f'Il faut {action}.','Il faut est suivi directement de l’infinitif.'),
  ('Avant de + infinitif',f'Avant {action}, je lis la consigne.',f'Avant {d}, je lis la consigne.','On emploie avant de devant l’infinitif, avec élision devant une voyelle.'),
  ('Essayer de + infinitif',f'J’essaie à {action}.',f'J’essaie {d}.','Essayer est suivi de de devant l’infinitif, avec élision si nécessaire.'),
  ('Pour + infinitif',f'Je prends du temps pour de {action}.',f'Je prends du temps pour {action}.','Pour est suivi directement de l’infinitif.')]
 developing=[
  ('L’hypothèse avec si',f'Si je pourrais {action}, je gagnerais du temps.',f'Si je pouvais {action}, je gagnerais du temps.','Dans cette hypothèse, si est suivi de l’imparfait, puis du conditionnel dans la principale.'),
  ('Se préparer à',f'Je me prépare de {action}.',f'Je me prépare à {action}.','Se préparer est suivi de à devant un infinitif.'),
  ('Une façon de',f'Je cherche une façon à {action}.',f'Je cherche une façon {d}.','On emploie une façon de suivie de l’infinitif.'),
  ('Éviter de',f'J’évite à tout changer avant {d}.',f'J’évite de tout changer avant {d}.','Éviter de est la construction attendue devant l’infinitif.'),
  ('S’intéresser à',f'Je m’intéresse de cette méthode pour {action}.',f'Je m’intéresse à cette méthode pour {action}.','S’intéresser se construit avec à.'),
  ('Permettre de',f'Cela me permet à {action}.',f'Cela me permet {d}.','Permettre à quelqu’un de faire quelque chose : ici, me représente la personne.'),
  ('Décider de',f'J’ai décidé à {action}.',f'J’ai décidé {d}.','Décider de est la construction attendue pour exprimer cette décision personnelle.'),
  ('Tenir à',f'Je tiens de {action}.',f'Je tiens à {action}.','Tenir à suivi d’un infinitif exprime l’importance que l’on donne à une action.')]
 stretching=[
  ('Il importe que + subjonctif',f'Il importe que je peux {action}.',f'Il importe que je puisse {action}.','Après il importe que, on attend ici le subjonctif.'),
  ('Encore faut-il + infinitif',f'Encore faut-il peut {action}.',f'Encore faut-il pouvoir {action}.','Après faut, le verbe pouvoir reste à l’infinitif.'),
  ('S’efforcer de',f'Je m’efforce à {action}, sans prétendre tout maîtriser.',f'Je m’efforce {d}, sans prétendre tout maîtriser.','S’efforcer de est la construction attendue.'),
  ('Pour peu que + subjonctif',f'Pour peu que je peux {action}, une première comparaison sera possible.',f'Pour peu que je puisse {action}, une première comparaison sera possible.','Pour peu que introduit cette condition avec le subjonctif.'),
  ('Quoi que et quoique',f'Quoiqu’il en soit, il reste possible {d}.',f'Quoi qu’il en soit, il reste possible {d}.','Quoi qu’il en soit s’écrit en trois mots : quoi que signifie ici quelle que soit la situation.'),
  ('Il ne suffit pas de',f'Il ne suffit pas à {action} pour conclure.',f'Il ne suffit pas {d} pour conclure.','Il suffit de exprime ici la condition suffisante ; à ne convient pas dans cette construction.'),
  ('À supposer que + subjonctif',f'À supposer que je peux {action}, il faudra vérifier le résultat.',f'À supposer que je puisse {action}, il faudra vérifier le résultat.','À supposer que demande ici le subjonctif.'),
  ('Le but est de',f'Le but est à {action}, non de multiplier les étapes.',f'Le but est {d}, non de multiplier les étapes.','Le but est de introduit ici l’action recherchée.')]
 return {level:dict(zip(['rule','mistake','correct','explanation'],values[(index+visit*3)%len(values)]))for level,values in [('foundation',foundation),('developing',developing),('stretching',stretching)]}

def additional_days():
 result=[]
 # Interleaving keeps revisits to a theme at least 56 days apart.
 for visit,lens in enumerate(LENSES):
  for index,subject in enumerate(THEMES):
   title,focus=subject['points'][visit]
   result.append(dict(title=title,group=subject['group'],paragraphs=[subject['opening'],focus,lens['close']],intermediate=lens['middle'],advanced=CATEGORY_REFLECTIONS[subject['group']]+' '+lens['advanced'],question=lens['question'],model=focus,expressions=[dict(zip(['expression','meaning','example'],item))for item in EXPRESSION_GROUPS[(index*7+visit*5)%len(EXPRESSION_GROUPS)]],grammar=contextual_grammar(subject['action'],index,visit)))
 return result[:334]
